import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

// Helper component for section titles
const SectionTitle = ({ title }) => (
  <h2 className="text-lg font-semibold text-primary mb-6 col-span-full">{title}</h2>
);

// Reusable form components
const FormInput = ({ label, name, ...props }) => (
  <div>
    <label htmlFor={name} className="block text-sm font-medium text-subtext-light mb-1">
      {label}
    </label>
    <input
      id={name}
      name={name}
      {...props}
      className="w-full bg-background-light dark:bg-gray-800 border border-border-light rounded-md shadow-sm px-3 py-2"
    />
  </div>
);

const FormSelect = ({ label, name, children, ...props }) => (
  <div>
    <label htmlFor={name} className="block text-sm font-medium text-subtext-light mb-1">
      {label}
    </label>
    <select
      id={name}
      name={name}
      {...props}
      className="w-full bg-background-light dark:bg-gray-800 border border-border-light rounded-md shadow-sm px-3 py-2"
    >
      {children}
    </select>
  </div>
);

const AddEmployeePage = () => {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    personalEmail: '',
    mobileNumber: '',
    gender: 'Male',
    employeeId: '',
    officialEmail: '',
    department: '',
    designation: '',
    joiningDate: '',
    employeeType: 'Full Time Employees',
    dateOfBirth: '',
    maritalStatus: 'Single',
    presentAddress: '',
    permanentAddress: '',
  });

  // 💡 Department-wise Designation Mapping
  const designationOptions = {
    'Faculty of Engineering': [
      'Professor',
      'Assistant Professor',
      'Associate Professor',
      'Lab Assistant',
      'Technical Staff',
    ],
    'Faculty of Arts & Commerce': [
      'Professor',
      'Lecturer',
      'Teaching Assistant',
      'Department Coordinator',
    ],
    'Faculty of Design': ['Professor', 'Design Mentor', 'Studio Assistant'],
    'Faculty of Management': [
      'Professor',
      'Visiting Faculty',
      'Research Coordinator',
    ],
    'Faculty of Foreign Language Department': [
      'Professor',
      'Language Instructor',
      'Translator',
    ],
    Administration: [
      'HR Manager',
      'Admin Officer',
      'Clerk',
      'Accountant',
      'IT Support Staff',
      'Receptionist',
    ],
  };

  const handleChange = (e) => {
    const { name, value } = e.target;

    // Reset designation if department changes
    if (name === 'department') {
      setFormData({ ...formData, department: value, designation: '' });
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    console.log('Submitting form data:', formData);
    try {
      await axios.post('http://127.0.0.1:8000/api/employees/', formData);
      alert('Employee added successfully!');
      navigate('/employees');
    } catch (error) {
      console.error('Error adding employee:', error);
      alert(
        `Failed to add staff member: ${
          error.response?.data ? JSON.stringify(error.response.data) : error.message
        }`
      );
    }
  };

  return (
    <div className="p-8">
      <div className="bg-card-light dark:bg-card-dark p-8 rounded-lg shadow-md">
        <h1 className="text-2xl font-bold text-text-light dark:text-text-dark mb-8">
          Add Employee
        </h1>

        <form onSubmit={handleSubmit} className="space-y-8">
          {/* ===== BASIC INFORMATION ===== */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-6">
            <SectionTitle title="Basic Information" />

            <div className="lg:col-span-2">
              <label className="block text-sm font-medium text-subtext-light mb-1">
                Name
              </label>
              <div className="grid grid-cols-2 gap-4">
                <input
                  name="firstName"
                  placeholder="First Name"
                  value={formData.firstName}
                  onChange={handleChange}
                  required
                  className="w-full bg-background-light dark:bg-gray-800 border border-border-light rounded-md shadow-sm px-3 py-2"
                />
                <input
                  name="lastName"
                  placeholder="Last Name"
                  value={formData.lastName}
                  onChange={handleChange}
                  required
                  className="w-full bg-background-light dark:bg-gray-800 border border-border-light rounded-md shadow-sm px-3 py-2"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-subtext-light mb-1">
                Gender *
              </label>
              <div className="flex items-center space-x-4 mt-2">
                <label>
                  <input
                    type="radio"
                    name="gender"
                    value="Male"
                    checked={formData.gender === 'Male'}
                    onChange={handleChange}
                    className="form-radio"
                  />{' '}
                  Male
                </label>
                <label>
                  <input
                    type="radio"
                    name="gender"
                    value="Female"
                    checked={formData.gender === 'Female'}
                    onChange={handleChange}
                    className="form-radio"
                  />{' '}
                  Female
                </label>
              </div>
            </div>

            <FormInput
              label="Personal Email *"
              name="personalEmail"
              type="email"
              value={formData.personalEmail}
              onChange={handleChange}
              required
            />

            <div>
              <label
                htmlFor="mobileNumber"
                className="block text-sm font-medium text-subtext-light mb-1"
              >
                Mobile Number *
              </label>
              <div className="flex">
                <span className="inline-flex items-center px-3 rounded-l-md border border-r-0 border-border-light bg-gray-50 text-subtext-light text-sm">
                  +91
                </span>
                <input
                  id="mobileNumber"
                  name="mobileNumber"
                  value={formData.mobileNumber}
                  onChange={handleChange}
                  className="flex-1 min-w-0 block w-full px-3 py-2 rounded-none rounded-r-md bg-background-light dark:bg-gray-800 border border-border-light"
                  type="text"
                  required
                />
              </div>
            </div>
          </div>

          {/* ===== WORK INFORMATION ===== */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-6">
            <SectionTitle title="Work Information" />

            <FormInput
              label="Employee ID *"
              name="employeeId"
              value={formData.employeeId}
              onChange={handleChange}
              required
            />
            <FormInput
              label="Official Email *"
              name="officialEmail"
              type="email"
              value={formData.officialEmail}
              onChange={handleChange}
              required
            />
            <FormInput
              label="Date of Joining *"
              name="joiningDate"
              type="date"
              value={formData.joiningDate}
              onChange={handleChange}
              required
            />

            {/* Department Dropdown */}
            <FormSelect
              label="Department *"
              name="department"
              value={formData.department}
              onChange={handleChange}
              required
            >
              <option value="">-- Select Department --</option>
              {Object.keys(designationOptions).map((dept) => (
                <option key={dept}>{dept}</option>
              ))}
            </FormSelect>

            {/* Dynamic Designation Dropdown */}
            <FormSelect
              label="Designation *"
              name="designation"
              value={formData.designation}
              onChange={handleChange}
              required
              disabled={!formData.department}
            >
              <option value="">
                {formData.department
                  ? '-- Select Designation --'
                  : 'Select a Department first'}
              </option>
              {formData.department &&
                designationOptions[formData.department].map((designation) => (
                  <option key={designation}>{designation}</option>
                ))}
            </FormSelect>

            <FormSelect
              label="Employee Type"
              name="employeeType"
              value={formData.employeeType}
              onChange={handleChange}
            >
              <option>Full Time Employees</option>
              <option>Part Time</option>
            </FormSelect>
          </div>

          {/* ===== PERSONAL INFORMATION ===== */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-6">
            <SectionTitle title="Personal Information" />

            <FormInput
              label="Date of Birth *"
              name="dateOfBirth"
              type="date"
              value={formData.dateOfBirth}
              onChange={handleChange}
              required
            />
            <FormSelect
              label="Marital Status *"
              name="maritalStatus"
              value={formData.maritalStatus}
              onChange={handleChange}
              required
            >
              <option>Single</option>
              <option>Married</option>
            </FormSelect>

            <div></div>

            <FormInput
              label="Present Address"
              name="presentAddress"
              value={formData.presentAddress}
              onChange={handleChange}
            />
            <FormInput
              label="Permanent Address"
              name="permanentAddress"
              value={formData.permanentAddress}
              onChange={handleChange}
            />
          </div>

          {/* ===== ACTION BUTTONS ===== */}
          <div className="mt-10 pt-6 border-t border-border-light flex justify-end gap-4">
            <button
              type="button"
              onClick={() => navigate('/employees')}
              className="bg-gray-200 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-300"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="bg-primary text-white px-6 py-2 rounded-lg hover:bg-blue-600"
            >
              Save Employee
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddEmployeePage;
